package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import org.springframework.stereotype.Component;
@Component public final class TranslationScenarioSchema {
 public static final String PREFIX="translation-scenario-v1\n",KIND="TRANSLATION";
 private final JsonMapper json=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,DeserializationFeature.FAIL_ON_TRAILING_TOKENS,DeserializationFeature.FAIL_ON_MISSING_CREATOR_PROPERTIES).propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).build();
 public record Term(String source,String target){}
 public record Segment(String key,String sectionId,PermissionProtocol.Basis source,String rightsRevision,DatasetProtocol.EvidenceRef evidence,String literal,List<String> protectedTokens){public Segment{protectedTokens=List.copyOf(protectedTokens);}}
 public record Selection(String schemaVersion,String scenarioKind,String sourceLanguage,String targetLanguage,String layoutPolicy,String semanticReviewInstruction,PermissionProtocol.Basis semanticReviewRule,List<Term> terminology,List<Segment> segments){public Selection{terminology=List.copyOf(terminology);segments=List.copyOf(segments);}}
 public Selection read(JsonNode n)throws Exception{try{var s=json.treeToValue(n,Selection.class);if(!"1.0.0".equals(s.schemaVersion())||!KIND.equals(s.scenarioKind())||!"ORDERED_TEXT_BLOCKS_EXACT_LINE_BREAKS".equals(s.layoutPolicy())||s.sourceLanguage().equals(s.targetLanguage())||s.segments().isEmpty()||s.segments().size()>64||s.terminology().size()>128)bad();for(String language:List.of(s.sourceLanguage(),s.targetLanguage()))if(!language.matches("[a-z]{2,3}(-[A-Za-z0-9]{2,8})*")||Locale.forLanguageTag(language).getLanguage().isBlank())bad();ProjectSchema.text(s.semanticReviewInstruction(),2000);basis(s.semanticReviewRule());var keys=new HashSet<String>();for(var segment:s.segments()){ProjectSchema.text(segment.key(),128);if(!keys.add(segment.key()))bad();WireValues.uuid(segment.sectionId());basis(segment.source());WireValues.uuid(segment.rightsRevision());ProjectSchema.text(segment.literal(),8000);new TaskSourceReadReceiptSchema(new PermissionSchema()).evidence(tree(segment.evidence()));if(!segment.source().version_id().equals(segment.evidence().sourceVersion())||segment.protectedTokens().size()>64||new HashSet<>(segment.protectedTokens()).size()!=segment.protectedTokens().size())bad();for(String token:segment.protectedTokens()){ProjectSchema.text(token,256);if(!segment.literal().contains(token))bad();}}
  keys.clear();for(var term:s.terminology()){ProjectSchema.text(term.source(),256);ProjectSchema.text(term.target(),256);if(!keys.add(term.source())||s.segments().stream().noneMatch(x->x.literal().contains(term.source())))bad();}return s;}catch(IllegalArgumentException|NullPointerException e){throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}}
 public JsonNode tree(Object o){return json.valueToTree(o);}public Selection definition(String d)throws Exception{if(!d.startsWith(PREFIX))bad();return read(json.readTree(d.substring(PREFIX.length())));}public String definition(JsonNode n)throws Exception{String d=PREFIX+new String(ContentReadAuthorization.canonicalBytes(tree(read(n))),java.nio.charset.StandardCharsets.UTF_8);if(d.length()>16000)bad();return d;}
 public void author(JsonNode a)throws Exception{String d=a.required("specification").required("INPUTS").required("definition").asText();if(!d.startsWith(PREFIX))return;var s=definition(d);var knowledge=new HashSet<PermissionProtocol.Basis>();for(var r:a.required("specification").required("APPLICABLE_KNOWLEDGE").required("evidence"))knowledge.add(basis(r));for(var segment:s.segments())if(!knowledge.contains(segment.source())||!a.required("project_id").asText().equals(segment.evidence().projectId()))bad();var rules=new HashSet<PermissionProtocol.Basis>();for(var r:a.required("specification").required("TASK_RULES").required("evidence"))rules.add(basis(r));if(!rules.contains(s.semanticReviewRule()))bad();}
 private PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(n.required("version_id").asText(),n.required("content_sha256").asText());}private static void basis(PermissionProtocol.Basis b){WireValues.uuid(b.version_id());WireValues.hash(b.content_sha256());}private static void bad(){throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}
}
